type Point=[number,number];
function curve(p0:Point,p1:Point,p2:Point,p3:Point){return Array.from({length:31},(_,i)=>{const t=i/30,u=1-t;return [u*u*u*p0[0]+3*u*u*t*p1[0]+3*u*t*t*p2[0]+t*t*t*p3[0],u*u*u*p0[1]+3*u*u*t*p1[1]+3*u*t*t*p2[1]+t*t*t*p3[1]] as Point;});}
function Membrane({points,color=blue}:{points:Point[];color?:string}){
 const sampled:Point[]=[];let dist=100;for(let i=0;i<points.length;i++){if(i)dist+=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);if(dist>=10){sampled.push(points[i]);dist=0;}}
 return <g><path d={points.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join(' ')} fill="none" stroke="#e9e3d0" strokeWidth={28}/>{sampled.map(([x,y],i)=>{const prev=sampled[Math.max(0,i-1)],next=sampled[Math.min(sampled.length-1,i+1)],a=Math.atan2(next[1]-prev[1],next[0]-prev[0])+Math.PI/2;return <g key={i}>{[-1,1].map(s=><g key={s}><path d={`M${x+s*11*Math.cos(a)} ${y+s*11*Math.sin(a)} L${x+s*2*Math.cos(a)-2*Math.sin(a)} ${y+s*2*Math.sin(a)+2*Math.cos(a)} M${x+s*11*Math.cos(a)+3*Math.sin(a)} ${y+s*11*Math.sin(a)-3*Math.cos(a)} L${x+s*3*Math.cos(a)+3*Math.sin(a)} ${y+s*3*Math.sin(a)-3*Math.cos(a)}`} stroke={color} strokeWidth={.9} opacity={.7}/><circle cx={x+s*14*Math.cos(a)} cy={y+s*14*Math.sin(a)} r={3.3} fill={color===blue?'#cee2e9':'#cee5db'} stroke={color} strokeWidth={.8}/></g>)}</g>;})}</g>;
}
